\set ON_ERROR_STOP on
begin;
insert into auth.users(id)select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,9)n;
create function pg_temp.assert_true(ok boolean,description text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',description;end if;end$$;
create function pg_temp.expect_failure(command text,description text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute command;exception when others then failed:=true;end;if not failed then raise exception 'FAILED unexpected success: %',description;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into contests(id,host_id,title,fields,event_start_at,registration_closes_at,ends_at)values('80000000-0000-4000-8000-000000000001',auth.uid(),'Awards privacy','[{"id":"20000000-0000-4000-8000-000000000001","type":"text","label":"Private","description":"","required":false}]',clock_timestamp()+interval '3 days',clock_timestamp()+interval '2 days',clock_timestamp()+interval '4 days');
insert into event_hosts(contest_id,user_id,role)values('80000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000006','manager'),('80000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000007','checkin');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select register_contest_entry('80000000-0000-4000-8000-000000000001','A','{}');
insert into contest_submissions(contest_id,user_id,participant_name,student_id,answers)values('80000000-0000-4000-8000-000000000001',auth.uid(),'Private original A','synthetic-private','{"20000000-0000-4000-8000-000000000001":"secret-unpublished-answer"}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select register_contest_entry('80000000-0000-4000-8000-000000000001','B','{}');
insert into contest_submissions(contest_id,user_id,participant_name,answers)values('80000000-0000-4000-8000-000000000001',auth.uid(),'Private original B','{}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select register_contest_entry('80000000-0000-4000-8000-000000000001','Voter','{}');
select pg_temp.assert_true(jsonb_array_length(contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'showcases')=0,'no implicit public submissions');
select pg_temp.assert_true((select count(*)=0 from contest_submissions),'other participants cannot read private submissions');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','configure','{"enabled":true}')$q$,'participant cannot configure');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000002","title":"Spoof"}')$q$,'cannot spoof other owner opt-in');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','configure','{"enabled":true}')$q$,'enabled requires closing time');
select contest_awards_api('80000000-0000-4000-8000-000000000001','configure',jsonb_build_object('enabled',true,'starts_at',clock_timestamp()+interval '1 hour','closes_at',clock_timestamp()+interval '1 day'));
select pg_temp.assert_true((select count(*)=4 from contest_award_categories),'four exact presets created');
select pg_temp.assert_true((select array_agg(name order by position)=array['Best Vibe Build','Best Agentic Connection','Most Creative Idea','People''s Choice'] from contest_award_categories),'exact award names retained');
select set_config('test.category',(select id::text from contest_award_categories order by position limit 1),true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','configure','{"results_published":true}')$q$,'cannot publish live votes');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000002","title":"Bad","demo_url":"javascript:alert(1)"}')$q$,'unsafe demo URL rejected');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000002","title":"Bad","demo_url":"https://user:secret@example.test/"}')$q$,'userinfo URL cannot publish credentials');
select contest_awards_api('80000000-0000-4000-8000-000000000001','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000002","title":"Opt-in A","summary":"Only public summary","demo_url":"https://example.test/a"}');
select set_config('test.a',(contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'my_showcases'->0->>'id'),true);
select pg_temp.expect_failure($q$select * from contest_showcases$q$,'raw showcase table cannot leak original identities');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select contest_awards_api('80000000-0000-4000-8000-000000000001','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000003","title":"Opt-in B"}');
select set_config('test.b',(contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'my_showcases'->0->>'id'),true);
select pg_temp.assert_true((contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'showcases')::text not like '%secret-unpublished-answer%' and(contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'showcases')::text not like '%synthetic-private%' and(contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'showcases')::text not like '%submission_user_id%','safe card projection excludes answers/identities');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.a')))$q$,'voting blocked before server start');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);
select contest_awards_api('80000000-0000-4000-8000-000000000001','configure',jsonb_build_object('starts_at',null));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.a')))$q$,'self vote denied');
select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.b')));
select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.b')));
select pg_temp.assert_true((select count(*)=1 from contest_award_ballots),'idempotent one ballot per category');
select pg_temp.expect_failure($q$insert into contest_award_ballots(contest_id,category_id,voter_id,showcase_id)values('80000000-0000-4000-8000-000000000001',current_setting('test.category')::uuid,auth.uid(),current_setting('test.a')::uuid)$q$,'raw REST cannot bypass vote validation');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.a')));
select pg_temp.assert_true((select count(*)=1 from contest_award_ballots),'other voter identities remain private');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','results')$q$,'participants cannot see live totals');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.assert_true(jsonb_array_length(contest_awards_api('80000000-0000-4000-8000-000000000001','state')->'showcases')=0,'nonparticipant cannot read cards');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.a')))$q$,'nonparticipant cannot vote');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from contest_award_ballots),'host does not get voter identities');
select pg_temp.assert_true((contest_awards_api('80000000-0000-4000-8000-000000000001','results')->'categories'->0->>'tied')::boolean,'ties displayed rather than randomly broken');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','configure',jsonb_build_object('closes_at',clock_timestamp()+interval '2 days'))$q$,'cannot extend deadline after ballots');
select contest_awards_api('80000000-0000-4000-8000-000000000001','close');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','configure','{"categories":[{"name":"Changed","description":"changed"}]}')$q$,'cannot replace categories after ballots');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','vote',jsonb_build_object('category_id',current_setting('test.category'),'showcase_id',current_setting('test.a')))$q$,'server clock close stops votes');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','results')$q$,'closed results private until published');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000006',true);
select contest_awards_api('80000000-0000-4000-8000-000000000001','configure','{"results_published":true}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.assert_true(jsonb_array_length(contest_awards_api('80000000-0000-4000-8000-000000000001','results')->'categories')=4,'authenticated outsider sees only published aggregate results');
select pg_temp.assert_true(contest_awards_api('80000000-0000-4000-8000-000000000001','results')::text not like '%voter_id%','results exclude voter identities');
select set_config('test.total',(contest_awards_api('80000000-0000-4000-8000-000000000001','results')->'categories'->0->>'total_votes'),true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
update event_registrations set status='cancelled' where contest_id='80000000-0000-4000-8000-000000000001' and user_id=auth.uid();
select pg_temp.assert_true((contest_awards_api('80000000-0000-4000-8000-000000000001','results')->'categories'->0->>'total_votes')=current_setting('test.total'),'closed tally stable after voter cancellation');
select contest_awards_api('80000000-0000-4000-8000-000000000001','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000002","enabled":false}');
select pg_temp.assert_true(contest_awards_api('80000000-0000-4000-8000-000000000001','results')::text not like '%Opt-in A%','withdrawal never reveals prior public content');
select pg_temp.assert_true((contest_awards_api('80000000-0000-4000-8000-000000000001','results')->'categories'->0->>'total_votes')=current_setting('test.total'),'withdrawal preserves closed vote totals');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000001','configure',jsonb_build_object('enabled',true,'closes_at',clock_timestamp()+interval '1 day'))$q$,'manual close cannot reopen');


select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into contests(id,host_id,title,fields,participation_mode,team_min_size,team_max_size,allow_individual_entries,registration_closes_at,event_start_at,ends_at)values('80000000-0000-4000-8000-000000000002',auth.uid(),'Team awards','[{"id":"20000000-0000-4000-8000-000000000001","type":"text","label":"Private","description":"","required":false}]','team',2,2,true,clock_timestamp()+interval '2 days',clock_timestamp()+interval '3 days',clock_timestamp()+interval '4 days');
select contest_awards_api('80000000-0000-4000-8000-000000000002','configure',jsonb_build_object('enabled',true,'closes_at',clock_timestamp()+interval '1 day'));
select set_config('test.teamcategory',(select id::text from contest_award_categories where contest_id='80000000-0000-4000-8000-000000000002'order by position limit 1),true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select register_contest_entry('80000000-0000-4000-8000-000000000002','Captain','{}','team_create','Team');
select set_config('test.team',(select id::text from contest_teams where contest_id='80000000-0000-4000-8000-000000000002'),true);
select set_config('test.code',(select join_code::text from contest_teams where contest_id='80000000-0000-4000-8000-000000000002'),true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select register_contest_entry('80000000-0000-4000-8000-000000000002','Member','{}','team_join',null,current_setting('test.code')::uuid);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
insert into contest_submissions(contest_id,user_id,team_id,participant_name,answers)values('80000000-0000-4000-8000-000000000002',auth.uid(),current_setting('test.team')::uuid,'Private team','{}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select contest_awards_api('80000000-0000-4000-8000-000000000002','showcase','{"submission_user_id":"00000000-0000-4000-8000-000000000002","title":"Team opt-in"}');
select set_config('test.teamcard',(contest_awards_api('80000000-0000-4000-8000-000000000002','state')->'my_showcases'->0->>'id'),true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000002','vote',jsonb_build_object('category_id',current_setting('test.teamcategory'),'showcase_id',current_setting('test.teamcard')))$q$,'own-team vote denied for nonowner teammate');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000002','vote',jsonb_build_object('category_id',current_setting('test.teamcategory'),'showcase_id',current_setting('test.teamcard')))$q$,'own-team vote denied for original submitter');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select register_contest_entry('80000000-0000-4000-8000-000000000002','Other voter','{}');
select contest_awards_api('80000000-0000-4000-8000-000000000002','vote',jsonb_build_object('category_id',current_setting('test.teamcategory'),'showcase_id',current_setting('test.teamcard')));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
update contests set approval_required=true where id='80000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000008',true);
select register_contest_entry('80000000-0000-4000-8000-000000000002','Pending voter','{}');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000002','vote',jsonb_build_object('category_id',current_setting('test.teamcategory'),'showcase_id',current_setting('test.teamcard')))$q$,'pending participant cannot vote');

-- Closing a scheduled vote before it starts records its original period and cannot reopen.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
insert into contests(id,host_id,title,fields)values('80000000-0000-4000-8000-000000000003',auth.uid(),'Scheduled awards','[{"id":"20000000-0000-4000-8000-000000000001","type":"text","label":"Private","description":"","required":false}]');
select contest_awards_api('80000000-0000-4000-8000-000000000003','configure',jsonb_build_object('enabled',true,'starts_at',clock_timestamp()+interval '2 hours','closes_at',clock_timestamp()+interval '1 day'));
select set_config('test.scheduled',(select starts_at::text from contest_award_settings where contest_id='80000000-0000-4000-8000-000000000003'),true);
select contest_awards_api('80000000-0000-4000-8000-000000000003','close');
select pg_temp.assert_true((select closed_manually and closed_at is not null and not enabled and starts_at is null and(closed_period->>'starts_at')::timestamptz=current_setting('test.scheduled')::timestamptz from contest_award_settings where contest_id='80000000-0000-4000-8000-000000000003'),'prestart close preserves scheduled period snapshot');
select pg_temp.expect_failure($q$select contest_awards_api('80000000-0000-4000-8000-000000000003','configure',jsonb_build_object('enabled',true,'closes_at',clock_timestamp()+interval '2 days'))$q$,'prestart manual close cannot reopen empty ballot');
rollback;
